// 6 - Match the Lead to the Right Team From Your Routing Table
// Your teams live in 0 - Config, one per line: Team name | what they handle | team inbox
// Add, rename or remove a team there. Nothing in this node needs editing.
const cfg = $('0 - Config: Your Settings').item.json;
const lead = $('2 - Clean Up Name, Email, Phone and Source').item.json;
const ai = $json.output || {};

const teams = String(cfg.routing_table || '')
  .split('\n')
  .map(line => line.split('|').map(part => part.trim()))
  .filter(parts => parts.length >= 3 && parts[2].includes('@'))
  .map(([name, handles, inbox]) => ({ name, handles, inbox }));

const wanted = String(ai.team || '').trim().toLowerCase();
const match = teams.find(t => t.name.toLowerCase() === wanted);

// A lead OpenAI cannot place goes to your default inbox, never nowhere.
return {
  json: {
    ...lead,
    score: ai.score,
    qualified: true,
    team: match ? match.name : 'Unassigned',
    team_email: match ? match.inbox : cfg.default_team_email,
    reason: ai.reason,
    summary: ai.summary,
    missing_info: ai.missing_info,
    status: match ? 'Sent to ' + match.name : 'Sent to default inbox',
    routed_at: $now.toISO(),
  },
};

