// 11 - Count Leads by Source, Team and Status
// Rebuilds the Dashboard tab from every row of the Tracker tab:
// one line per measure, counted for today, the last 7 days, the last 30 days and all time.
const rows = $input.all().map(item => item.json);
const now = DateTime.now();
const since = {
  today: now.startOf('day'),
  last_7_days: now.minus({ days: 7 }),
  last_30_days: now.minus({ days: 30 }),
};
const isTrue = value => String(value).toLowerCase() === 'true';
const received = row => DateTime.fromISO(String(row.received_at));

const lines = [];
const count = (metric, test) => {
  const hits = rows.filter(test);
  lines.push({
    metric,
    today: hits.filter(r => received(r) >= since.today).length,
    last_7_days: hits.filter(r => received(r) >= since.last_7_days).length,
    last_30_days: hits.filter(r => received(r) >= since.last_30_days).length,
    all_time: hits.length,
    updated_at: now.toISO(),
  });
};

count('All leads', () => true);
count('Qualified', r => isTrue(r.qualified));
count('Not qualified', r => !isTrue(r.qualified));
count('Still waiting for first contact', r => String(r.status || '').startsWith('Sent to'));

const distinct = key => [...new Set(rows.map(r => r[key]).filter(Boolean))];
// Which source brings qualified leads, not just the most leads.
distinct('source').forEach(s => count('Qualified from ' + s, r => r.source === s && isTrue(r.qualified)));
distinct('team').forEach(t => count('Team: ' + t, r => r.team === t));
distinct('status').forEach(s => count('Status: ' + s, r => r.status === s));

return lines.map(line => ({ json: line }));

